  trump: {desc:"President of the United States (2017–2021; since 2025)", extract:"Donald John Trump is an American politician, media personality, and businessman who is the 47th president of the United States. A member of the Republican Party, he served as the 45th president from 2017 to 2021.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Official_Presidential_Portrait_of_President_Donald_J._Trump_%282025%29.jpg/330px-Official_Presidential_Portrait_of_President_Donald_J._Trump_%282025%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Donald_Trump"},
  netanyahu: {desc:"Prime Minister of Israel (1996–1999; 2009–2021; 2022–present)", extract:"Benjamin \"Bibi\" Netanyahu is an Israeli politician and diplomat who has served as Prime Minister of Israel since 2022. Having previously held office from 1996 to 1999 and from 2009 to 2021, Netanyahu is Israel's longest-serving prime minister.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Benjamin_Netanyahu%2C_February_2023.jpg/330px-Benjamin_Netanyahu%2C_February_2023.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Benjamin_Netanyahu"},
  xi: {desc:"Leader of China since 2012", extract:"Xi Jinping is a Chinese politician who is the paramount leader of China. He has served as the general secretary of the Chinese Communist Party (CCP) and chairman of the Party Central Military Commission (CMC) since 2012, and as the president of China and chairman of the State Central Military Commission since 2013.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Prime_Minister_Keir_Starmer_visits_China_%2855066713683%29_%28cropped%2Bangle%29.jpg/330px-Prime_Minister_Keir_Starmer_visits_China_%2855066713683%29_%28cropped%2Bangle%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Xi_Jinping"},
  modi: {desc:"Prime Minister of India since 2014", extract:"Narendra Damodardas Modi is an Indian politician who has served as the prime minister of India since 26 May 2014. Modi was the chief minister of Gujarat from 2001 to 2014 and is the Member of Parliament (MP) for Varanasi. He is a member of the Bharatiya Janata Party (BJP) and of the Rashtriya Swayamsevak Sangh (RSS), a right-wing Hindutva paramilitary volunteer organisation. He is India's third-longest-serving prime minister, and the longest-serving prime minister outside the Indian National Congress.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/The_official_portrait_of_Shri_Narendra_Modi%2C_the_Prime_Minister_of_the_Republic_of_India.jpg/330px-The_official_portrait_of_Shri_Narendra_Modi%2C_the_Prime_Minister_of_the_Republic_of_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Narendra_Modi"},
  milei: {desc:"President of Argentina since 2023", extract:"Javier Gerardo Milei is an Argentine politician and economist who has served as the president of Argentina since 2023. He previously served as a member of the Chamber of Deputies from 2021 to 2023.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Javier_Milei_in_pull-aside_meeting_at_the_United_Nations_Headquarters_%283x4_cropped%29.jpg/330px-Javier_Milei_in_pull-aside_meeting_at_the_United_Nations_Headquarters_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Javier_Milei"},
  ramaphosa: {desc:"President of South Africa since 2018", extract:"Matamela Cyril Ramaphosa is a South African businessman and politician who is serving as the fifth president of South Africa since 2018. A former anti-apartheid activist and trade union leader, Ramaphosa is also the president of the African National Congress (ANC).", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Cyril_Ramaphosa_in_2026.jpg/330px-Cyril_Ramaphosa_in_2026.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Cyril_Ramaphosa"},
  tolam: {desc:"General secretary of the Communist Party of Vietnam since 2024", extract:"Tô Lâm is a Vietnamese politician and former police officer who since 2024 has served as the general secretary of the Communist Party of Vietnam (CPV), the highest-ranked position of the Vietnamese politics, and as the current President of Vietnam since 2026. He previously served as president from May to October 2024. A veteran of the People's Public Security Forces with over 40 years of service, Lâm rose through the ranks to become Minister of Public Security in 2016, a position he held until his first election to the presidency in 2024.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/T%C3%B4_L%C3%A2m_20260519_%28cropped%29.jpg/330px-T%C3%B4_L%C3%A2m_20260519_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/T%C3%B4_L%C3%A2m"},
