  tinubu: {desc:"President of Nigeria since 2023", extract:"Asiwaju Bola Ahmed Adekunle Tinubu is a Nigerian politician serving as the 16th and current president of Nigeria since 2023. He previously served as the governor of Lagos State from 1999 to 2007 and senator for Lagos West in the Third Republic.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Bola_Tinubu_portrait.jpg/330px-Bola_Tinubu_portrait.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Bola_Tinubu"},
  pezeshkian: {desc:"President of Iran since 2024", extract:"Masoud Pezeshkian is an Iranian politician and heart surgeon who has served as the ninth president of Iran since 2024. A member of the reformist faction, he is the oldest person to serve in this position, taking office at the age of 69.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Masoud_Pezeshkian_2025_%28cropped%29.jpg/330px-Masoud_Pezeshkian_2025_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Masoud_Pezeshkian"},
  mkhamenei: {desc:"Supreme Leader of Iran since 2026", extract:"Mojtaba Hosseini Khamenei is an Iranian politician and Shia cleric who has served as the third supreme leader of Iran since 2026. A member of the Khamenei family and the second son of second supreme leader Ali Khamenei, he previously served as Vakil of the Supreme Leader during his father's rule from 2008 to 2026.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Portrait_of_Mojtaba_Khamenei.jpg/330px-Portrait_of_Mojtaba_Khamenei.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Mojtaba_Khamenei"},
  sheinbaum: {desc:"President of Mexico since 2024", extract:"Claudia Sheinbaum Pardo is a Mexican politician, energy and climate change scientist, and academic who has been serving as the 66th president of Mexico since 2024. She is the first woman and the first person with Jewish heritage to hold the office. A member of the National Regeneration Movement (Morena), she previously served as Head of Government of Mexico City from 2018 to 2023. In 2025, Forbes ranked Sheinbaum as the fifth most powerful woman in the world.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Claudia_Sheinbaum_in_2025_%283x4_cropped%29.jpg/330px-Claudia_Sheinbaum_in_2025_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Claudia_Sheinbaum"},
